#[derive(Clone)]
struct MatchState {
    position: usize,
    captures: Vec<Vec<ElementId>>,
    matched: Vec<ElementId>,
}

fn apply_rule(
    rule: &SchemaRule,
    input: &[ElementId],
    elements: &[ElementRecord],
    state: MatchState,
) -> Vec<MatchState> {
    match rule {
        SchemaRule::Any => {
            let Some(element) = input.get(state.position) else {
                return Vec::new();
            };
            let mut state = state;
            state.position += 1;
            state.matched.push(*element);
            vec![state]
        }
        SchemaRule::Node(kinds) => {
            let Some((offset, element)) =
                input[state.position..]
                    .iter()
                    .enumerate()
                    .find(|(_, element)| {
                        element_is_node(elements, **element)
                            && kinds.contains(&element_kind(elements, **element))
                    })
            else {
                return Vec::new();
            };
            let mut state = state;
            state.position += offset + 1;
            state.matched.push(*element);
            vec![state]
        }
        SchemaRule::Token(kind) => {
            let Some((offset, element)) =
                input[state.position..]
                    .iter()
                    .enumerate()
                    .find(|(_, element)| {
                        !element_is_node(elements, **element)
                            && element_kind(elements, **element) == *kind
                    })
            else {
                return Vec::new();
            };
            let mut state = state;
            state.position += offset + 1;
            state.matched.push(*element);
            vec![state]
        }
        SchemaRule::Seq(rules) => rules.iter().fold(vec![state], |states, rule| {
            states
                .into_iter()
                .flat_map(|state| apply_rule(rule, input, elements, state))
                .collect()
        }),
        SchemaRule::Alt(rules) => rules
            .iter()
            .flat_map(|rule| apply_rule(rule, input, elements, state.clone()))
            .collect(),
        SchemaRule::Optional(rule) => {
            let mut states = apply_rule(rule, input, elements, state.clone());
            states.push(state);
            states
        }
        SchemaRule::Repeated(rule) => {
            let mut results = vec![state.clone()];
            let mut frontier = vec![state];
            while !frontier.is_empty() {
                let mut next = Vec::new();
                for state in frontier {
                    for matched in apply_rule(rule, input, elements, state.clone()) {
                        if matched.position > state.position {
                            next.push(matched);
                        }
                    }
                }
                results.extend(next.iter().cloned());
                frontier = next;
            }
            results.reverse();
            results
        }
        SchemaRule::Capture { slot, rule } => {
            let matched_start = state.matched.len();
            apply_rule(rule, input, elements, state)
                .into_iter()
                .map(|mut state| {
                    state.captures[*slot].extend_from_slice(&state.matched[matched_start..]);
                    state
                })
                .collect()
        }
    }
}

pub(super) fn validate_node(
    syntax: &SyntaxNode,
    input: &[ElementId],
    elements: &[ElementRecord],
) -> Result<Vec<Vec<ElementId>>, StrongAstError> {
    let Some(schema) = SCHEMAS.iter().find(|schema| schema.kind == syntax.kind()) else {
        return Ok(Vec::new());
    };
    let initial = MatchState {
        position: 0,
        captures: vec![Vec::new(); schema.field_count],
        matched: Vec::new(),
    };
    apply_rule(schema.rule, input, elements, initial)
        .into_iter()
        .find(|state| input.iter().all(|element| state.matched.contains(element)))
        .map(|state| state.captures)
        .ok_or(StrongAstError::InvalidStructure {
            kind: syntax.kind(),
            at: syntax.text_range(),
        })
}

